BEGIN READ ONLY;
SET LOCAL statement_timeout='10s';
SET LOCAL lock_timeout='2s';
SELECT jsonb_build_object('identity',jsonb_build_object('database',current_database(),'role',current_user,'read_only',current_setting('transaction_read_only'),'version',version()),'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'version',extversion)) FROM pg_extension WHERE extname IN ('pg_cron','pgcrypto')),'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations),'raid_tables',(SELECT jsonb_agg(relname ORDER BY relname) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'raid_room%'),'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'md5',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'acl',p.proacl::text) ORDER BY p.proname) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND (p.proname LIKE '%raid%' OR p.proname IN ('claim_present','resolve_battle','finalize_battle_replay'))),'cron_jobs',(SELECT jsonb_agg(jsonb_build_object('jobid',jobid,'name',jobname,'schedule',schedule,'active',active,'command_md5',md5(command))) FROM cron.job),'cron_recent',(SELECT jsonb_agg(t) FROM (SELECT jobid,status,start_time,end_time FROM cron.job_run_details ORDER BY start_time DESC LIMIT 20)t)) AS audit;
ROLLBACK;
